// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, address actor, uint256 ts) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 0, 1000 ether);
        vm.warp(bound(ts, 2, type(uint48).max)); // ensure block.timestamp > pastBlockTime (0)

        vm.deal(actor, amount <= actor.balance ? actor.balance : amount);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");

        // General rule: the call succeeds if and only if msg.value == 10 ether.
        assertTrue(ok == (amount == 10 ether));
    }
}
